#pragma once
namespace forkrot {
inline constexpr char HARDWARE_PAGE[] = R"HWHTML(<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Оборудование · G5500</title><style>body{font:16px system-ui;background:#101721;color:#e5edf5;margin:0;padding:20px}main{max-width:760px;margin:auto}a{color:#6bc9ff}h1{font-size:26px}fieldset{border:1px solid #405267;border-radius:12px;margin:20px 0;padding:18px}label{display:block;margin:14px 0}select,input,button{font:inherit;background:#1b2a3b;color:inherit;border:1px solid #71869c;border-radius:6px;padding:9px;max-width:100%;box-sizing:border-box}select{display:block;width:100%;margin-top:5px}input[type=number]{width:100%}button{cursor:pointer;margin:8px 8px 8px 0}button:disabled{opacity:.45;cursor:default}p{line-height:1.5}.note{padding:14px;border:1px solid #71869c;border-radius:8px}.error{color:#ffb3a5}small{color:#b3c4d5}#message{white-space:pre-wrap}output{font-weight:600}</style>
<main><a href="/">← Управление</a><h1>Оборудование</h1><p class="note" id="state" role="status">Загрузка состояния…</p>
<p id="effective"></p><p>Изменения применяются после перезагрузки. В течение двух минут откройте эту страницу и подтвердите настройки. До подтверждения движение заблокировано. Если подтверждение недоступно, устройство перейдёт в восстановление.</p>
<form id="hardware"><fieldset><legend>Привод</legend><label>Интерфейс<select name="driveInterface"><option value="0">Штатный блок Yaesu</option><option value="1">Направления и отдельный PWM</option><option value="2">BTS7960 / IBT-2</option></select></label>
<label>Режим<select name="simulation"><option value="0">Физический привод</option><option value="1">Имитация движения</option></select></label>
<label>Выходы BTS7960<select name="pwmInverted"><option value="0">Прямое подключение PWM</option><option value="1">Инвертирующие оптроны RPWM / LPWM</option></select></label><small>Выбирайте по подключённой схеме. ENABLE всегда активен HIGH. CrowPanel без адаптера не управляет физическим приводом.</small></fieldset>
<fieldset><legend>Сеть и Bluetooth</legend><label>Bluetooth<select name="bluetoothEnabled"><option value="0">Выключен</option><option value="1">Включён</option></select></label>
<label>Транспорт<select name="bluetoothMode"><option value="3">Автоматически по плате</option><option value="1">Внешний HC-05</option><option value="2">Встроенный SPP · ESP32</option></select></label>
<label>Точка доступа ESP32<select name="forceApSta"><option value="0">Резервная: при потере сети</option><option value="1">Постоянная: вместе с домашней сетью</option></select></label><small>Постоянная AP и встроенный SPP требуют дополнительной внутренней памяти. На S2/S3 точка доступа сохраняется при подключении к роутеру.</small></fieldset>
<fieldset><legend>Кнопка подтверждения цели</legend><label>GPIO · −1 отключает кнопку<input name="buttonGpio" type="number" min="-1" max="48" step="1" required></label>
<label>Уровень нажатия<select name="buttonActiveLow"><option value="1">LOW · замыкание на GND</option><option value="0">HIGH</option></select></label>
<label>Подтяжка<select name="buttonPullup"><option value="1">Внутренняя к питанию</option><option value="0">Внешняя</option></select></label><small>Для CrowPanel используется кнопка ручки; GPIO должен оставаться −1. Поведение загрузчика на BOOT не изменяется.</small></fieldset>
<button id="save" disabled>Сохранить и перезапустить</button></form>
<div><button type="button" id="confirm" disabled>Подтвердить и перезапустить</button><button type="button" id="rollback" disabled>Вернуть подтверждённые настройки</button><button type="button" id="recover" disabled>Режим восстановления</button></div>
<p id="message" role="status" aria-live="polite"></p><p><a href="/recovery">Страница восстановления</a> · <a href="/">Основной интерфейс</a></p></main>
<script>'use strict';let state,dirty=false,busy=false,probe=false;const form=document.getElementById('hardware'),msg=document.getElementById('message');
const names=['driveInterface','simulation','bluetoothEnabled','bluetoothMode','forceApSta','buttonGpio','buttonActiveLow','buttonPullup','pwmInverted'];
const reasons={unconfirmed:'Предыдущий запуск не подтверждён.',low_memory:'Недостаточно внутренней памяти.',allocation_failed:'Зафиксирован отказ выделения памяти.',radio_failed:'Не удалось запустить радио.',storage_failed:'Не удалось проверить запись настроек.',invalid_config:'Настройки несовместимы с оборудованием.',requested:'Восстановление включено вручную.',initial_setup:'Выберите подключённое оборудование и сохраните настройки.',none:''};
const errors={no_confirmed_configuration:'Подтверждённых настроек пока нет.',invalid_form:'Проверьте все значения.',stale_configuration:'Страница устарела. Обновите состояние.',not_ready:'Ожидаем проверку доступности настроек и запаса памяти.',storage_failed:'Запись не подтверждена. Настройки не применены.',gpio_conflict:'Выбранный GPIO занят.',invalid_button_gpio:'GPIO или подтяжка недоступны.',spp_not_supported:'Встроенный SPP доступен только на обычной ESP32.',drive_not_supported:'Этот привод недоступен для выбранной платы.',crowpanel_hardware_fixed:'Привод недоступен в этой сборке CrowPanel; GPIO кнопки должен быть −1.',crowpanel_uart_is_drive:'В этой сборке RX/TX управляют приводом. HC-05 и HUD по UART недоступны.',uart_in_use_by_hc05:'UART занят HC-05. Отключите HUD по UART перед изменением.',invalid_hardware:'Проверьте интерфейс и инверсию PWM.'};
form.addEventListener('input',()=>dirty=true);
async function request(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),5000);try{const r=await fetch(path,{cache:'no-store',signal:controller.signal,...(body?{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(body)}:{})});const j=await r.json();if(!r.ok)throw Error(errors[j.error]||j.error||'Запрос отклонён');return j;}finally{clearTimeout(timer);}}
const credentials=()=>({token:state.token,generation:state.generation});
function buttons(){document.getElementById('save').disabled=busy||!state;document.getElementById('confirm').disabled=busy||!state?.trial||!state.ready||!probe;document.getElementById('rollback').disabled=busy||!state?.hasConfirmed;document.getElementById('recover').disabled=busy||!state||state.recovery;}
async function refresh(){if(busy)return;try{const next=await request('/api/hardware');if(state&&(state.token!==next.token||state.generation!==next.generation))probe=false;state=next;document.getElementById('state').textContent=state.recovery?'Режим восстановления. Привод и Bluetooth отключены. '+(reasons[state.reason]||''):state.trial?'Пробный запуск. До отката: '+Math.ceil(state.remainingMs/1000)+' с.':'Работают подтверждённые настройки.';document.getElementById('effective').textContent='Свободная внутренняя память: '+state.heapFree+' байт; крупнейший блок: '+state.heapMaxBlock+' байт. Bluetooth: '+state.backend+'.';if(!dirty)for(const name of names)form.elements[name].value=state.configured[name];form.elements.bluetoothMode.options[2].disabled=!state.sppSupported;form.elements.forceApSta.disabled=!state.classicEsp32;form.elements.driveInterface.options[1].disabled=!(state.separateDrive??state.independentDrive);form.elements.driveInterface.options[2].disabled=!(state.btsDrive??state.independentDrive);form.elements.bluetoothEnabled.disabled=!!state.crowpanelLocalDrive;if(state.crowpanelLocalDrive)form.elements.bluetoothEnabled.value="0";form.elements.buttonGpio.readOnly=state.crowpanel;if(state.trial&&state.ready&&!probe){await request('/api/hardware/probe',credentials());probe=true;}buttons();}catch(e){msg.textContent='Не удалось получить состояние: '+e.message;document.getElementById('confirm').disabled=true;}}
async function apply(path,values){if(busy||!state)return;busy=true;msg.textContent='Сохраняем настройки…';buttons();try{await request(path,{...credentials(),...values});msg.textContent='Сохранено. Устройство перезапускается. После подключения откройте эту страницу.';dirty=false;probe=false;setTimeout(()=>{busy=false;refresh();},4000);}catch(e){msg.textContent=e.message;busy=false;buttons();}}
form.addEventListener('submit',e=>{e.preventDefault();const body={};for(const name of names)body[name]=form.elements[name].value;apply('/api/hardware',body);});
document.getElementById('confirm').onclick=()=>apply('/api/hardware/confirm',{});document.getElementById('rollback').onclick=()=>apply('/api/hardware/rollback',{});document.getElementById('recover').onclick=()=>apply('/api/hardware/recovery',{});refresh();setInterval(refresh,2000);
</script></html>)HWHTML";
} // namespace forkrot
